window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-609b78fcfa2993b1"]={"versions": [{"id": "FIG-609b78fcfa2993b1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Tailoring von primitiven Attributen im Rahmen des AUTOSAR Standardization Template (<code>DataFormatElementScope</code>). Es modelliert Spezialisierungen und Assoziationen zur Einschränkung von Werten, Multiplizitäten und Variabilitäten sowie die Standardwertbehandlung für XML- bzw. Modell-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Enumerationen sowie deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AttributeTailoring</code>: Abstrakte Basisklasse im Paket/Kontext <code>DataFormatElementScope</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+multiplicityRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>MultiplicityRestrictionWithSeverity</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+variationRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>VariationRestrictionWithSeverity</code>.</li>\n<li><code>PrimitiveAttributeTailoring</code>: Spezialisiert per Generalisierung <code>AttributeTailoring</code>.</li>\n<li>Attribut: <code>+ defaultValueHandling :DefaultValueApplicationStrategyEnum [0..1]</code>.</li>\n<li>Rekursive Kompositionsbeziehung auf sich selbst: Rolle <code>+subAttributeTailoring</code>, Multiplizität <code>[0..*]</code>.</li>\n<li>Kompositionsbeziehung <code>+valueRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>ValueRestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Übergeordnetes Konzept für mit Schweregrad versehene Einschränkungen, konkretisiert durch:</li>\n<li><code>MultiplicityRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractMultiplicityRestriction</code>.</li>\n<li><code>VariationRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractVariationRestriction</code>.</li>\n<li><code>ValueRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractValueRestriction</code>.</li>\n<li><code>AbstractMultiplicityRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ lowerMultiplicity :PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicity :PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicityInfinite :Boolean [0..1]</code></li>\n<li><code>AbstractVariationRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ validBindingTime :FullBindingTimeEnum [0..*]</code></li>\n<li><code>+ variation :Boolean [0..1]</code></li>\n<li><code>AbstractValueRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ max :Limit [0..1]</code></li>\n<li><code>+ maxLength :PositiveInteger [0..1]</code></li>\n<li><code>+ min :Limit [0..1]</code></li>\n<li><code>+ minLength :PositiveInteger [0..1]</code></li>\n<li><code>+ pattern :RegularExpression [0..1]</code></li>\n<li><code>«enumeration» DefaultValueApplicationStrategyEnum</code>: Definiert Strategien zur Anwendung von Standardwerten mit den Literalen:</li>\n<li><code>noDefault</code></li>\n<li><code>defaultIfRevisionUpdate</code></li>\n<li><code>defaultIfUndefined</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Instanziierung erfolgt deklarativ innerhalb der Modellkonfiguration eines Standardisierungsprofils zur Validierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der Metamodell-Elemente für Werkzeuge zur Validierung und Anpassung von AUTOSAR-Modellen. Werkzeuge müssen sicherstellen, dass bei der Anwendung eines <code>PrimitiveAttributeTailoring</code> die definierten Restriktionen (<code>MultiplicityRestrictionWithSeverity</code>, <code>VariationRestrictionWithSeverity</code>, <code>ValueRestrictionWithSeverity</code>) gegen die Modellinstanzen ausgewertet werden und das Verhalten bezüglich Vorgabewerten gemäß <code>DefaultValueApplicationStrategyEnum</code> umgesetzt wird.</p>"}, {"id": "FIG-511f328dd124afa2", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Tailoring von primitiven Attributen im Rahmen des AUTOSAR Standardization Template (<code>DataFormatElementScope</code>). Es modelliert Spezialisierungen und Assoziationen zur Einschränkung von Werten, Multiplizitäten und Variabilitäten sowie die Standardwertbehandlung für XML- bzw. Modell-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Enumerationen sowie deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AttributeTailoring</code>: Abstrakte Basisklasse im Paket/Kontext <code>DataFormatElementScope</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+multiplicityRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>MultiplicityRestrictionWithSeverity</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+variationRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>VariationRestrictionWithSeverity</code>.</li>\n<li><code>PrimitiveAttributeTailoring</code>: Spezialisiert per Generalisierung <code>AttributeTailoring</code>.</li>\n<li>Attribut: <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>.</li>\n<li>Rekursive Kompositionsbeziehung auf sich selbst: Rolle <code>+subAttributeTailoring</code>, Multiplizität <code>[0..*]</code>.</li>\n<li>Kompositionsbeziehung <code>+valueRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>ValueRestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Übergeordnetes Konzept für mit Schweregrad versehene Einschränkungen, konkretisiert durch:</li>\n<li><code>MultiplicityRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractMultiplicityRestriction</code>.</li>\n<li><code>VariationRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractVariationRestriction</code>.</li>\n<li><code>ValueRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractValueRestriction</code>.</li>\n<li><code>AbstractMultiplicityRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ lowerMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicityInfinite: Boolean [0..1]</code></li>\n<li><code>AbstractVariationRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ validBindingTime: FullBindingTimeEnum [0..*]</code></li>\n<li><code>+ variation: Boolean [0..1]</code></li>\n<li><code>AbstractValueRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ max: Limit [0..1]</code></li>\n<li><code>+ maxLength: PositiveInteger [0..1]</code></li>\n<li><code>+ min: Limit [0..1]</code></li>\n<li><code>+ minLength: PositiveInteger [0..1]</code></li>\n<li><code>+ pattern: RegularExpression [0..1]</code></li>\n<li><code>«enumeration» DefaultValueApplicationStrategyEnum</code>: Definiert Strategien zur Anwendung von Standardwerten mit den Literalen:</li>\n<li><code>noDefault</code></li>\n<li><code>defaultIfRevisionUpdate</code></li>\n<li><code>defaultIfUndefined</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Instanziierung erfolgt deklarativ innerhalb der Modellkonfiguration eines Standardisierungsprofils zur Validierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der Metamodell-Elemente für Werkzeuge zur Validierung und Anpassung von AUTOSAR-Modellen. Werkzeuge müssen sicherstellen, dass bei der Anwendung eines <code>PrimitiveAttributeTailoring</code> die definierten Restriktionen (<code>MultiplicityRestrictionWithSeverity</code>, <code>VariationRestrictionWithSeverity</code>, <code>ValueRestrictionWithSeverity</code>) gegen die Modellinstanzen ausgewertet werden und das Verhalten bezüglich Vorgabewerten gemäß <code>DefaultValueApplicationStrategyEnum</code> umgesetzt wird.</p>"}, {"id": "FIG-8518e15593f4095e", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Tailoring von primitiven Attributen im Rahmen des AUTOSAR Standardization Template (<code>DataFormatElementScope</code>). Es modelliert Spezialisierungen und Assoziationen zur Einschränkung von Werten, Multiplizitäten und Variabilitäten sowie die Standardwertbehandlung für XML- bzw. Modell-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Enumerationen sowie deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AttributeTailoring</code>: Abstrakte Basisklasse im Paket/Kontext <code>DataFormatElementScope</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+multiplicityRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>MultiplicityRestrictionWithSeverity</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+variationRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>VariationRestrictionWithSeverity</code>.</li>\n<li><code>PrimitiveAttributeTailoring</code>: Spezialisiert per Generalisierung <code>AttributeTailoring</code>.</li>\n<li>Attribut: <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>.</li>\n<li>Rekursive Kompositionsbeziehung auf sich selbst: Rolle <code>+subAttributeTailoring</code>, Multiplizität <code>[0..*]</code>.</li>\n<li>Kompositionsbeziehung <code>+valueRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>ValueRestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Übergeordnetes Konzept für mit Schweregrad versehene Einschränkungen, konkretisiert durch:</li>\n<li><code>MultiplicityRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractMultiplicityRestriction</code>.</li>\n<li><code>VariationRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractVariationRestriction</code>.</li>\n<li><code>ValueRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractValueRestriction</code>.</li>\n<li><code>AbstractMultiplicityRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ lowerMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicityInfinite: Boolean [0..1]</code></li>\n<li><code>AbstractVariationRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ validBindingTime: FullBindingTimeEnum [0..*]</code></li>\n<li><code>+ variation: Boolean [0..1]</code></li>\n<li><code>AbstractValueRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ max: Limit [0..1]</code></li>\n<li><code>+ maxLength: PositiveInteger [0..1]</code></li>\n<li><code>+ min: Limit [0..1]</code></li>\n<li><code>+ minLength: PositiveInteger [0..1]</code></li>\n<li><code>+ pattern: RegularExpression [0..1]</code></li>\n<li><code>«enumeration» DefaultValueApplicationStrategyEnum</code>: Definiert Strategien zur Anwendung von Standardwerten mit den Literalen:</li>\n<li><code>noDefault</code></li>\n<li><code>defaultIfRevisionUpdate</code></li>\n<li><code>defaultIfUndefined</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Instanziierung erfolgt deklarativ innerhalb der Modellkonfiguration eines Standardisierungsprofils zur Validierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der Metamodell-Elemente für Werkzeuge zur Validierung und Anpassung von AUTOSAR-Modellen. Werkzeuge müssen sicherstellen, dass bei der Anwendung eines <code>PrimitiveAttributeTailoring</code> die definierten Restriktionen (<code>MultiplicityRestrictionWithSeverity</code>, <code>VariationRestrictionWithSeverity</code>, <code>ValueRestrictionWithSeverity</code>) gegen die Modellinstanzen ausgewertet werden und das Verhalten bezüglich Vorgabewerten gemäß <code>DefaultValueApplicationStrategyEnum</code> umgesetzt wird.</p>"}, {"id": "FIG-0cd313c293e795fe", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Tailoring von primitiven Attributen im Rahmen des AUTOSAR Standardization Template (<code>DataFormatElementScope</code>). Es modelliert Spezialisierungen und Assoziationen zur Einschränkung von Werten, Multiplizitäten und Variabilitäten sowie die Standardwertbehandlung für XML- bzw. Modell-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Enumerationen sowie deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AttributeTailoring</code>: Abstrakte Basisklasse im Paket/Kontext <code>DataFormatElementScope</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+multiplicityRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>MultiplicityRestrictionWithSeverity</code>.</li>\n<li>Besitzt eine Kompositionsbeziehung <code>+variationRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>VariationRestrictionWithSeverity</code>.</li>\n<li><code>PrimitiveAttributeTailoring</code>: Spezialisiert per Generalisierung <code>AttributeTailoring</code>.</li>\n<li>Attribut: <code>+ defaultValueHandling: DefaultValueApplicationStrategyEnum [0..1]</code>.</li>\n<li>Rekursive Kompositionsbeziehung auf sich selbst: Rolle <code>+subAttributeTailoring</code>, Multiplizität <code>[0..*]</code>.</li>\n<li>Kompositionsbeziehung <code>+valueRestriction</code> mit Multiplizität <code>[0..1]</code> zu <code>ValueRestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Übergeordnetes Konzept für mit Schweregrad versehene Einschränkungen, konkretisiert durch:</li>\n<li><code>MultiplicityRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractMultiplicityRestriction</code>.</li>\n<li><code>VariationRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractVariationRestriction</code>.</li>\n<li><code>ValueRestrictionWithSeverity</code>: Generalisiert die abstrakte Klasse <code>AbstractValueRestriction</code>.</li>\n<li><code>AbstractMultiplicityRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ lowerMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicity: PositiveInteger [0..1]</code></li>\n<li><code>+ upperMultiplicityInfinite: Boolean [0..1]</code></li>\n<li><code>AbstractVariationRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ validBindingTime: FullBindingTimeEnum [0..*]</code></li>\n<li><code>+ variation: Boolean [0..1]</code></li>\n<li><code>AbstractValueRestriction</code>: Abstrakte Klasse mit den Attributen:</li>\n<li><code>+ max: Limit [0..1]</code></li>\n<li><code>+ maxLength: PositiveInteger [0..1]</code></li>\n<li><code>+ min: Limit [0..1]</code></li>\n<li><code>+ minLength: PositiveInteger [0..1]</code></li>\n<li><code>+ pattern: RegularExpression [0..1]</code></li>\n<li><code>«enumeration» DefaultValueApplicationStrategyEnum</code>: Definiert Strategien zur Anwendung von Standardwerten mit den Literalen:</li>\n<li><code>noDefault</code></li>\n<li><code>defaultIfRevisionUpdate</code></li>\n<li><code>defaultIfUndefined</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Instanziierung erfolgt deklarativ innerhalb der Modellkonfiguration eines Standardisierungsprofils zur Validierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der Metamodell-Elemente für Werkzeuge zur Validierung und Anpassung von AUTOSAR-Modellen. Werkzeuge müssen sicherstellen, dass bei der Anwendung eines <code>PrimitiveAttributeTailoring</code> die definierten Restriktionen (<code>MultiplicityRestrictionWithSeverity</code>, <code>VariationRestrictionWithSeverity</code>, <code>ValueRestrictionWithSeverity</code>) gegen die Modellinstanzen ausgewertet werden und das Verhalten bezüglich Vorgabewerten gemäß <code>DefaultValueApplicationStrategyEnum</code> umgesetzt wird.</p>"}], "trans": [{"from": "FIG-609b78fcfa2993b1", "to": "FIG-511f328dd124afa2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Attributdefinitionen in <code>PrimitiveAttributeTailoring</code>, <code>AbstractMultiplicityRestriction</code>, <code>AbstractVariationRestriction</code> und <code>AbstractValueRestriction</code>: Der Leerraum vor dem Doppelpunkt des Typ-Trenners wurde entfernt (z. B. <code>defaultValueHandling :DefaultValueApplicationStrategyEnum</code> zu <code>defaultValueHandling: DefaultValueApplicationStrategyEnum</code>).</li>\n</ul>"}, {"from": "FIG-511f328dd124afa2", "to": "FIG-8518e15593f4095e", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8518e15593f4095e", "to": "FIG-0cd313c293e795fe", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
